#include "eqnolefilehdr.hxx"
#include <sot/storage.hxx>
bool GetMathTypeVersion( SotStorage* pStor, sal_uInt8 &nVersion )
{
    sal_uInt8 nVer = 0;
    bool bSuccess = false;


    // code snippet copied from MathType::Parse

    rtl::Reference<SotStorageStream> xSrc = pStor->OpenSotStream(
        u"Equation Native"_ustr,
        StreamMode::STD_READ);
    if ( (!xSrc.is()) || (ERRCODE_NONE != xSrc->GetError()))
        return bSuccess;
    SotStorageStream *pS = xSrc.get();
    pS->SetEndian( SvStreamEndian::LITTLE );

    EQNOLEFILEHDR aHdr;
    aHdr.Read(pS);
    pS->ReadUChar( nVer );

    if (!pS->GetError())
    {
        nVersion = nVer;
        bSuccess = true;
    }
    return bSuccess;
}
